INSERT OR IGNORE INTO "ai_messages" ("id", "conversation_id", "role", "content", "citations_json", "confidence", "safety_flag", "created_at") VALUES ('msg_msugktj5l60mmobu','conv_msugktj533ccint8','user','What are the stair riser and tread limits in the Ghana Building Code?','[]',NULL,NULL,'2026-08-15T14:15:46.049Z');
INSERT OR IGNORE INTO "ai_messages" ("id", "conversation_id", "role", "content", "citations_json", "confidence", "safety_flag", "created_at") VALUES ('msg_msugktm9dv7xatrb','conv_msugktj533ccint8','assistant','Based on the GHBC regulatory source library, the following sources are most relevant to "What are the stair riser and tread limits in the Ghana Building Code?".

1. GS 1207:2018, Part 11 §11.29, 11.29.10.2 (informational): not maintain stepped aisle riser and tread dimensions.

2. GS 1207:2018, Part 11 §11.15, 11.15.4 (prohibited): The triangular openings at the open sides of a stair, formed by the riser, tread and bottom rail shall not allow passage of a sphere 152 mm (6 inches) in diameter.

3. GS 1207:2018, Part 11 §11.29, 11.29.10.1 (informational): Transitions to stairways that maintain stepped aisle riser and tread dimensions.

4. GS 1207:2018, Part 29, 29.6.12.1 (fire): This clause applies to mechanical and passive smoke control systems that are required by the Ghana Building Code or the Ghana Fire Code.

5. GS 1207:2018, Part 11 §11.16, 11.17.3.1 (mandatory): The measurement along stairways shall be made on a plane parallel and tangent to the stair tread nosings in the center of the stair and landings.

6. GS 1207:2018, Part 11 §11.11, 11.11.5.2 (mandatory): Stair riser heights shall be 178 mm (7 inches) maximum and 102 mm (4 inches) minimum.

GHBC interpretation — not an official determination by the issuing authority. Professional verification required. The LLM copilot is unavailable; this is a deterministic retrieval answer.','[{"requirement_id":"GHBC-REQ-010772","source_document":"GS 1207:2018","part":11,"section":"11.29","clause":"11.29.10.2","page":567,"snippet":"not maintain stepped aisle riser and tread dimensions.","status":"verified"},{"requirement_id":"GHBC-REQ-010115","source_document":"GS 1207:2018","part":11,"section":"11.15","clause":"11.15.4","page":544,"snippet":"The triangular openings at the open sides of a stair, formed by the riser, tread and bottom rail shall not allow passage of a sphere 152 mm (6 inches) in diameter.","status":"needs_verification"},{"requirement_id":"GHBC-REQ-010770","source_document":"GS 1207:2018","part":11,"section":"11.29","clause":"11.29.10.1","page":567,"snippet":"Transitions to stairways that maintain stepped aisle riser and tread dimensions.","status":"verified"},{"requirement_id":"GHBC-REQ-023210","source_document":"GS 1207:2018","part":29,"section":null,"clause":"29.6.12.1","page":1235,"snippet":"This clause applies to mechanical and passive smoke control systems that are required by the Ghana Building Code or the Ghana Fire Code.","status":"verified"},{"requirement_id":"GHBC-REQ-010209","source_document":"GS 1207:2018","part":11,"section":"11.16","clause":"11.17.3.1","page":547,"snippet":"The measurement along stairways shall be made on a plane parallel and tangent to the stair tread nosings in the center of the stair and landings.","status":"verified"},{"requirement_id":"GHBC-REQ-009815","source_document":"GS 1207:2018","part":11,"section":"11.11","clause":"11.11.5.2","page":533,"snippet":"Stair riser heights shall be 178 mm (7 inches) maximum and 102 mm (4 inches) minimum.","status":"verified"},{"requirement_id":"GHBC-REQ-009823","source_document":"GS 1207:2018","part":11,"section":"11.11","clause":"11.11.5.2","page":533,"snippet":"permitted to use the riser/tread dimension in Clause 11.29.14.2.","status":"verified"},{"requirement_id":"GHBC-REQ-010066","source_document":"GS 1207:2018","part":11,"section":"11.14","clause":"11.14.6","page":542,"snippet":"Where handrails are not continuous between flights, the handrails shall extend horizontally not less than 305 mm (12 inches) beyond the top riser and continue to slope for the depth of one tread beyond the bottom riser.","status":"verified"}]',0.7459247708585972,'REVIEW_REQUIRED','2026-08-15T14:15:46.161Z');
INSERT OR IGNORE INTO "ai_messages" ("id", "conversation_id", "role", "content", "citations_json", "confidence", "safety_flag", "created_at") VALUES ('msg_msugnfrpelkqvaoj','conv_msugnfrp5kcslcyz','user','What are the stair riser and tread limits in the Ghana Building Code?','[]',NULL,NULL,'2026-08-15T14:17:48.181Z');
INSERT OR IGNORE INTO "ai_messages" ("id", "conversation_id", "role", "content", "citations_json", "confidence", "safety_flag", "created_at") VALUES ('msg_msugnfw8mc3ajc8t','conv_msugnfrp5kcslcyz','assistant','Based on the GHBC regulatory source library, the following sources are most relevant to "What are the stair riser and tread limits in the Ghana Building Code?".

1. GS 1207:2018, Part 11 §11.29, 11.29.10.2 (informational): not maintain stepped aisle riser and tread dimensions.

2. GS 1207:2018, Part 11 §11.15, 11.15.4 (prohibited): The triangular openings at the open sides of a stair, formed by the riser, tread and bottom rail shall not allow passage of a sphere 152 mm (6 inches) in diameter.

3. GS 1207:2018, Part 11 §11.29, 11.29.10.1 (informational): Transitions to stairways that maintain stepped aisle riser and tread dimensions.

4. GS 1207:2018, Part 29, 29.6.12.1 (fire): This clause applies to mechanical and passive smoke control systems that are required by the Ghana Building Code or the Ghana Fire Code.

5. GS 1207:2018, Part 11 §11.16, 11.17.3.1 (mandatory): The measurement along stairways shall be made on a plane parallel and tangent to the stair tread nosings in the center of the stair and landings.

6. GS 1207:2018, Part 11 §11.11, 11.11.5.2 (mandatory): Stair riser heights shall be 178 mm (7 inches) maximum and 102 mm (4 inches) minimum.

