INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-1','T','he provisions of this part shall control the classification of all buildings and structures as to occupancy and use','The provisions of this part shall control the classification of all buildings and structures as to occupancy and use. Different classifications of occupancy and use represent varying levels of hazard and risk to building occupants and adjacent properties.',3,'3.1','3.1.1',163,'The provisions of this part shall control the classification of all buildings and structures as to occupancy and use. Different classifications of occupancy and use represent varying levels of hazard and risk to building occupants and adjacent properties.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-2','O','ccupancy classification is the formal designation of the primary purpose of the building, structure or portion thereof','Occupancy classification is the formal designation of the primary purpose of the building, structure or portion thereof. Structures shall be classified into one or more of the occupancy groups listed in this clause based on the nature of the hazards and risks to building occupants generally associated with the intended purpose of the building or structure. An area, room or space that is intended to be occupied at different times for different purposes shall comply with all applicable requirements associated with such potential multipurpose. Structures containing multiple occupancy groups shall comply with this Code. Where a structure is proposed for a purpose that is not specifically listed in this clause, such structure shall be classified in the occupancy it most nearly resembles based on the fire safety and relative hazard. Occupied roofs shall be classified in the group that the occupancy most nearly resembles, according to the fire safety and relative hazard, and shall comply with this Code. 1. Assembly Clause 3.3 Groups A-1, A-2, A-3, A-4 and A-5. 2. Business Clause 3.4 Group B. 3. Educational Clause 3.5 Group E. 4. Factory and Industrial Clause 3.6 Groups F-1 and F-2. 5. High Hazard Clause 3.7 Groups H-1, H-2, H-3, H-4 and H-5. 6. Institutional Clause 3.8 Groups I-1, I-2, I-3 and I-4. 7. Mercantile Clause 3.9 Group M. 8. Residential Clause 3.10 Groups R-1, R-2, R-3 and R-4. 9. Storage Clause 3.11 Groups S-1 and S-2. 10. Utility and Miscellaneous Clause 3.12 Group U.',3,'3.2','3.2.1',163,'Occupancy classification is the formal designation of the primary purpose of the building, structure or portion thereof. Structures shall be classified into one or more of the occupancy groups listed in this clause based on the nature of the hazards and risks to building occupants generally associated with the intended purpose of the building or structure. An area, room or space that is intended to be occupied at different times for different purposes shall comply with all applicable requirements associated with such potential multipurpose. Structures containing multiple occupancy groups shall comply with this Code. Where a structure is proposed for a purpose that is not specifically listed in this clause, such structure shall be classified in the occupancy it most nearly resembles based on the fire safety and relative hazard. Occupied roofs shall be classified in the group that the occupancy most nearly resembles, according to the fire safety and relative hazard, and shall comply with this Code. 1. Assembly Clause 3.3 Groups A-1, A-2, A-3, A-4 and A-5. 2. Business Clause 3.4 Group B. 3. Educational Clause 3.5 Group E. 4. Factory and Industrial Clause 3.6 Groups F-1 and F-2. 5. High Hazard Clause 3.7 Groups H-1, H-2, H-3, H-4 and H-5. 6. Institutional Clause 3.8 Groups I-1, I-2, I-3 and I-4. 7. Mercantile Clause 3.9 Group M. 8. Residential Clause 3.10 Groups R-1, R-2, R-3 and R-4. 9. Storage Clause 3.11 Groups S-1 and S-2. 10. Utility and Miscellaneous Clause 3.12 Group U.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-3','O','ccupancy groups contain subordinate uses having similar hazards and risks to building occupants','Occupancy groups contain subordinate uses having similar hazards and risks to building occupants. Uses include, but are not limited to, those functional designations listed within the occupancy group descriptions in Clause 3.2.1. Certain uses require specific limitations and controls in accordance with the provisions of part 4 and else where in this Code.',3,'3.2','3.2.2',163,'Occupancy groups contain subordinate uses having similar hazards and risks to building occupants. Uses include, but are not limited to, those functional designations listed within the occupancy group descriptions in Clause 3.2.1. Certain uses require specific limitations and controls in accordance with the provisions of part 4 and else where in this Code.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-4','A','ssembly Group A occupancy includes, among others, the use of a building or structure, or a portion thereof, for the gathering of persons for purposes such as civic, social or religious functions; recreation, food or drink consumption or awaiting transportation','Assembly Group A occupancy includes, among others, the use of a building or structure, or a portion thereof, for the gathering of persons for purposes such as civic, social or religious functions; recreation, food or drink consumption or awaiting transportation.',3,'3.3','3.3.1',163,'Assembly Group A occupancy includes, among others, the use of a building or structure, or a portion thereof, for the gathering of persons for purposes such as civic, social or religious functions; recreation, food or drink consumption or awaiting transportation.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-5','A','building or tenant space used for assembly purposes with an occupant load of less than 50 persons shall be classified as a Group B occupancy','A building or tenant space used for assembly purposes with an occupant load of less than 50 persons shall be classified as a Group B occupancy.',3,'3.3','3.3.1.1',163,'A building or tenant space used for assembly purposes with an occupant load of less than 50 persons shall be classified as a Group B occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-6','T','he following rooms and spaces shall not be classified as Assembly occupancies:','The following rooms and spaces shall not be classified as Assembly occupancies: 1. A room or space used for assembly purposes with an occupant load of less than 50 persons and accessory to another occupancy shall be classified as a Group B occupancy or as part of that occupancy. 2. A room or space used for assembly purposes that is less than 70 m2 (750 square feet) in area and accessory to another occupancy shall be classified as a Group B occupancy or as part of that occupancy.',3,'3.3','3.3.1.2',163,'The following rooms and spaces shall not be classified as Assembly occupancies: 1. A room or space used for assembly purposes with an occupant load of less than 50 persons and accessory to another occupancy shall be classified as a Group B occupancy or as part of that occupancy. 2. A room or space used for assembly purposes that is less than 70 m2 (750 square feet) in area and accessory to another occupancy shall be classified as a Group B occupancy or as part of that occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-7','A','1 occupancy includes assembly uses, usually with fixed seating, intended for the production and viewing of the performing arts or motion pictures including, but not limited to:','Group A-1 occupancy includes assembly uses, usually with fixed seating, intended for the production and viewing of the performing arts or motion pictures including, but not limited to: Motion picture theaters Symphony and concert halls Television and radio studios admitting an audience Theaters',3,'3.3','3.3.2',164,'Group A-1 occupancy includes assembly uses, usually with fixed seating, intended for the production and viewing of the performing arts or motion pictures including, but not limited to: Motion picture theaters Symphony and concert halls Television and radio studios admitting an audience Theaters');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-8','A','2 occupancy includes assembly uses intended for food and/or drink consumption including, but not limited to:','Group A-2 occupancy includes assembly uses intended for food and/or drink consumption including, but not limited to: Banquet halls Casinos (gaming areas) Nightclubs Restaurants, cafeterias and similar dining facilities (including associated commercial kitchens) Taverns and bars',3,'3.3','3.3.3',164,'Group A-2 occupancy includes assembly uses intended for food and/or drink consumption including, but not limited to: Banquet halls Casinos (gaming areas) Nightclubs Restaurants, cafeterias and similar dining facilities (including associated commercial kitchens) Taverns and bars');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-9','A','3 occupancy includes assembly uses intended for worship, recreation or amusement and other assembly uses not classified elsewhere in Group A including, but not limited to:','Group A-3 occupancy includes assembly uses intended for worship, recreation or amusement and other assembly uses not classified elsewhere in Group A including, but not limited to: Amusement arcades Art galleries Bowling alleys Community halls Courtrooms Dance halls (not including food or drink consumption) Exhibition halls Funeral parlors Greenhouses for the conservation and exhibition of plants that provide public access. Gymnasiums (without spectator seating) Indoor swimming pools (without spectator seating) Indoor tennis courts (without spectator seating) Lecture halls Libraries Museums Places of religious worship Pool and billiard parlors Waiting areas in transportation terminals',3,'3.3','3.3.4',164,'Group A-3 occupancy includes assembly uses intended for worship, recreation or amusement and other assembly uses not classified elsewhere in Group A including, but not limited to: Amusement arcades Art galleries Bowling alleys Community halls Courtrooms Dance halls (not including food or drink consumption) Exhibition halls Funeral parlors Greenhouses for the conservation and exhibition of plants that provide public access. Gymnasiums (without spectator seating) Indoor swimming pools (without spectator seating) Indoor tennis courts (without spectator seating) Lecture halls Libraries Museums Places of religious worship Pool and billiard parlors Waiting areas in transportation terminals');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-10','A','4 occupancy includes assembly uses intended for viewing of indoor sporting events and activities with spectator seating including, but not limited to:','Group A-4 occupancy includes assembly uses intended for viewing of indoor sporting events and activities with spectator seating including, but not limited to: Arenas Skating rinks Swimming pools Tennis courts',3,'3.3','3.3.5',164,'Group A-4 occupancy includes assembly uses intended for viewing of indoor sporting events and activities with spectator seating including, but not limited to: Arenas Skating rinks Swimming pools Tennis courts');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-11','A','5 occupancy includes assembly uses intended for participation in or viewing outdoor activities including, but not limited to:','Group A-5 occupancy includes assembly uses intended for participation in or viewing outdoor activities including, but not limited to: Amusement park structures Bleachers Grandstands Stadiums',3,'3.3','3.3.6',164,'Group A-5 occupancy includes assembly uses intended for participation in or viewing outdoor activities including, but not limited to: Amusement park structures Bleachers Grandstands Stadiums');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-12','B','usiness Group B occupancy includes, among others, the use of a building or structure, or a portion thereof, for office, professional or service-type transactions, including storage of records and accounts','Business Group B occupancy includes, among others, the use of a building or structure, or a portion thereof, for office, professional or service-type transactions, including storage of records and accounts. Business occupancies shall include, but not be limited to, the following: Airport traffic control towers Ambulatory care facilities Animal hospitals, kennels and pounds Banks Barber and beauty shops Car wash Civic administration Clinic, outpatient Dry cleaning and laundries: pick-up and delivery stations and self-service. Educational occupancies for students above the 12th grade. Electronic data processing Food processing establishments and commercial kitchens not associated with restaurants, cafeterias and similar dining facilities not more than 232 m2 (2,500 square feet) in area. Laboratories: testing and research Motor vehicle showrooms Post offices Print shops Professional services (architects, attorneys, dentists, physicians, engineers, etc.). Radio and television stations Telephone exchanges Training and skill development not in a school or academic program (this shall include, but not be limited to, tutoring centers, martial arts studios, gymnastics and similar uses regardless of the ages served, and where not classified as a Group A occupancy).',3,'3.4','3.4.1',164,'Business Group B occupancy includes, among others, the use of a building or structure, or a portion thereof, for office, professional or service-type transactions, including storage of records and accounts. Business occupancies shall include, but not be limited to, the following: Airport traffic control towers Ambulatory care facilities Animal hospitals, kennels and pounds Banks Barber and beauty shops Car wash Civic administration Clinic, outpatient Dry cleaning and laundries: pick-up and delivery stations and self-service. Educational occupancies for students above the 12th grade. Electronic data processing Food processing establishments and commercial kitchens not associated with restaurants, cafeterias and similar dining facilities not more than 232 m2 (2,500 square feet) in area. Laboratories: testing and research Motor vehicle showrooms Post offices Print shops Professional services (architects, attorneys, dentists, physicians, engineers, etc.). Radio and television stations Telephone exchanges Training and skill development not in a school or academic program (this shall include, but not be limited to, tutoring centers, martial arts studios, gymnastics and similar uses regardless of the ages served, and where not classified as a Group A occupancy).');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-13','E','ducational Group E occupancy includes, among others, the use of a building or structure, or a portion thereof, by six or more persons at any one time for educational purposes through the 12th grade','Educational Group E occupancy includes, among others, the use of a building or structure, or a portion thereof, by six or more persons at any one time for educational purposes through the 12th grade.',3,'3.5.1',NULL,165,'Educational Group E occupancy includes, among others, the use of a building or structure, or a portion thereof, by six or more persons at any one time for educational purposes through the 12th grade.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-14','T','his group includes buildings and structures or portions thereof occupied by more than five children older than 21 / years of age who receive educational, supervision or personal2 care services for fewer than 24 hours per day','This group includes buildings and structures or portions thereof occupied by more than five children older than 21 / years of age who receive educational, supervision or personal2 care services for fewer than 24 hours per day.',3,'3.5.1','3.5.2',165,'This group includes buildings and structures or portions thereof occupied by more than five children older than 21 / years of age who receive educational, supervision or personal2 care services for fewer than 24 hours per day.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-15','R','ooms and spaces within places of religious worship providing such day care during religious functions shall be classified as part of the primary occupancy','Rooms and spaces within places of religious worship providing such day care during religious functions shall be classified as part of the primary occupancy.',3,'3.5.1','3.5.2.1',165,'Rooms and spaces within places of religious worship providing such day care during religious functions shall be classified as part of the primary occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-16','A','facility having five or fewer children receiving such day care shall be classified as part of the primary occupancy','A facility having five or fewer children receiving such day care shall be classified as part of the primary occupancy.',3,'3.5.1','3.5.2.2',165,'A facility having five or fewer children receiving such day care shall be classified as part of the primary occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-17','F','actory Industrial Group F occupancy includes, among others, the use of a building or structure, or a portion thereof, for assembling, disassembling, fabricating, finishing, manufacturing, packaging, repair or processing operations that are not classified as a Group H hazardous or Group S storage occupancy','Factory Industrial Group F occupancy includes, among others, the use of a building or structure, or a portion thereof, for assembling, disassembling, fabricating, finishing, manufacturing, packaging, repair or processing operations that are not classified as a Group H hazardous or Group S storage occupancy.',3,'3.6','3.6.1',165,'Factory Industrial Group F occupancy includes, among others, the use of a building or structure, or a portion thereof, for assembling, disassembling, fabricating, finishing, manufacturing, packaging, repair or processing operations that are not classified as a Group H hazardous or Group S storage occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-18','F','1','Group F-1. Factory industrial uses that are not classified as Factory Industrial F-2 Low Hazard shall be classified as F-1 Moderate Hazard and shall include, but not be limited to, the following: Aircraft (manufacturing, not to include repair) Appliances Athletic equipment Automobiles and other motor vehicles Bakeries Beverages: over 16-percent alcohol content Bicycles Boats Brooms or brushes Business machines Cameras and photo equipment Canvas or similar fabric Carpets and rugs (includes cleaning) Clothing Construction and agricultural machinery Disinfectants Dry cleaning and dyeing Electric generation plants Electronics Engines (including rebuilding) Food processing establishments and commercial kitchens not associated with restaurants, cafeterias and similar dining facilities more than 232 m2 (2,500 square feet) in area. Furniture Hemp products Jute products Laundries Leather products Machinery Metals Millwork (sash and door) Motion pictures and television filming (without spectators) Musical instruments Optical goods Paper mills or products Photographic film Plastic products Printing or publishing Recreational vehicles Refuse incineration Shoes Soaps and detergents Textiles Tobacco Trailers Upholstering Wood; distillation Woodworking (cabinet)',3,'3.6','3.6.2',165,'Group F-1. Factory industrial uses that are not classified as Factory Industrial F-2 Low Hazard shall be classified as F-1 Moderate Hazard and shall include, but not be limited to, the following: Aircraft (manufacturing, not to include repair) Appliances Athletic equipment Automobiles and other motor vehicles Bakeries Beverages: over 16-percent alcohol content Bicycles Boats Brooms or brushes Business machines Cameras and photo equipment Canvas or similar fabric Carpets and rugs (includes cleaning) Clothing Construction and agricultural machinery Disinfectants Dry cleaning and dyeing Electric generation plants Electronics Engines (including rebuilding) Food processing establishments and commercial kitchens not associated with restaurants, cafeterias and similar dining facilities more than 232 m2 (2,500 square feet) in area. Furniture Hemp products Jute products Laundries Leather products Machinery Metals Millwork (sash and door) Motion pictures and television filming (without spectators) Musical instruments Optical goods Paper mills or products Photographic film Plastic products Printing or publishing Recreational vehicles Refuse incineration Shoes Soaps and detergents Textiles Tobacco Trailers Upholstering Wood; distillation Woodworking (cabinet)');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-19','F','2','F-2. Factory industrial uses that involve the fabrication or manufacturing of noncombustible materials that during finishing, packing or processing do not involve a significant fire hazard shall be classified as F-2 occupancies and shall include, but not be limited to, the following: Beverages: up to and including 16-percent alcohol content Brick and masonry Ceramic products Foundries Glass products Gypsum Ice Metal products (fabrication and assembly)',3,'3.6','3.6.3',166,'F-2. Factory industrial uses that involve the fabrication or manufacturing of noncombustible materials that during finishing, packing or processing do not involve a significant fire hazard shall be classified as F-2 occupancies and shall include, but not be limited to, the following: Beverages: up to and including 16-percent alcohol content Brick and masonry Ceramic products Foundries Glass products Gypsum Ice Metal products (fabrication and assembly)');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-20','H','igh-hazard Group H occupancy includes, among others, the use of a building or structure, or a portion thereof, that involves the manufacturing, processing, generation or storage of materials that constitute a physical or health hazard in quantities in excess of those allowed in control areas complying with this Code based on the maximum allowable quantity limits for control areas set forth in','High-hazard Group H occupancy includes, among others, the use of a building or structure, or a portion thereof, that involves the manufacturing, processing, generation or storage of materials that constitute a physical or health hazard in quantities in excess of those allowed in control areas complying with this Code based on the maximum allowable quantity limits for control areas set forth in Tables 3.1.1(1) and 3.7.1(2). Hazardous occupancies are classified in Groups H-1, H-2, H-3, H-4 and H-5 and shall be in accordance with this clause, the requirements of this Code and the Ghana Fire Code. Hazardous materials stored, or used on top of roofs or canopies, shall be classified as outdoor storage or use and shall comply with the Ghana Fire Code.',3,'3.7','3.7.1',166,'High-hazard Group H occupancy includes, among others, the use of a building or structure, or a portion thereof, that involves the manufacturing, processing, generation or storage of materials that constitute a physical or health hazard in quantities in excess of those allowed in control areas complying with this Code based on the maximum allowable quantity limits for control areas set forth in Tables 3.1.1(1) and 3.7.1(2). Hazardous occupancies are classified in Groups H-1, H-2, H-3, H-4 and H-5 and shall be in accordance with this clause, the requirements of this Code and the Ghana Fire Code. Hazardous materials stored, or used on top of roofs or canopies, shall be classified as outdoor storage or use and shall comply with the Ghana Fire Code.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-21','F','or SI: 1 cubic foot = 0','For SI: 1 cubic foot = 0.028 m3 , 1 pound = 0.454 kg, 1 gallon = 3.785 L. NL = Not Limited; NA = Not Applicable; UD = Unclassified Detonable. a. For use of control areas, see Clause 4.14.2. b. The aggregate quantity in use and storage shall not exceed the quantity listed for storage. c. The quantities of alcoholic beverages in retail and wholesale sales occupancies shall not be limited provided the liquids are packaged in individual containers not exceeding 1.3 gallons. In retail and wholesale sales occupancies, the quantities of medicines, foodstuffs or consumer products, and cosmetics containing not more than 50 percent by volume of water-miscible liquids with the remainder of the solutions not being flammable, shall not be limited, provided that such materials are packaged in individual containers not exceeding 1.3 gallons. d. Maximum allowable quantities shall be increased 100 percent in buildings equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. Where Note e also applies, the increase for both notes shall be applied accumulatively. e. Maximum allowable quantities shall be increased 100 percent when stored in approved storage cabinets, day boxes, gas cabinets, gas rooms or exhausted enclosures or in listed safety cans in accordance with Clause 5003.9.10 of the Ghana Fire Code. Where Note d also applies, the increase for both notes shall be applied accumulatively. f. Quantities shall not be limited in a building equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. g. Allowed only in buildings equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. h. Containing not more than the maximum allowable quantity per control area of Class IA, IB or IC flammable liquids. i. The maximum allowable quantity shall not apply to fuel oil storage complying with the Ghana Fire Code. j. Quantities in parentheses indicate quantity units in parentheses at the head of each column. k. A maximum quantity of 220 pounds of solid or 22 gallons of liquid Class 3 oxidizers is allowed when such materials are necessary for maintenance purposes, operation or sanitation of equipment when the storage containers and the manner of storage are approved. l. Net weight of the pyrotechnic composition of the fireworks. Where the net weight of the pyrotechnic composition of the fireworks is not known, 25 percent of the gross weight of the fireworks, including packaging, shall be used. m. For gallons of liquids, divide the amount in pounds by 10 in accordance with the Ghana Fire Code. n. For storage and display quantities in Group M and storage quantities in Group S occupancies complying with this Code. o. Densely packed baled cotton that complies with the packing requirements of ISO 8115 shall not be included in this material class. p. The following shall not be included in determining the maximum allowable quantities: 1. Liquid or gaseous fuel in fuel tanks on vehicles. 2. Liquid or gaseous fuel in fuel tanks on motorized equipment operated in accordance with the Ghana Fire Code. 3. Gaseous fuels in piping systems and fixed appliances regulated by this Code. 4. Liquid fuels in piping systems and fixed appliances regulated by this Code. 5. Alcohol-based hand rubs classified as Class I or II liquids in dispensers that are installed in accordance with the Ghana Fire Code. The location of the alcohol-based hand rub (ABHR) dispensers shall be provided in the construction documents. q. Where manufactured, generated or used in such a manner that the concentration and conditions create a fire or explosion hazard based on information prepared in accordance with this Code.',3,NULL,NULL,169,'For SI: 1 cubic foot = 0.028 m3 , 1 pound = 0.454 kg, 1 gallon = 3.785 L. NL = Not Limited; NA = Not Applicable; UD = Unclassified Detonable. a. For use of control areas, see Clause 4.14.2. b. The aggregate quantity in use and storage shall not exceed the quantity listed for storage. c. The quantities of alcoholic beverages in retail and wholesale sales occupancies shall not be limited provided the liquids are packaged in individual containers not exceeding 1.3 gallons. In retail and wholesale sales occupancies, the quantities of medicines, foodstuffs or consumer products, and cosmetics containing not more than 50 percent by volume of water-miscible liquids with the remainder of the solutions not being flammable, shall not be limited, provided that such materials are packaged in individual containers not exceeding 1.3 gallons. d. Maximum allowable quantities shall be increased 100 percent in buildings equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. Where Note e also applies, the increase for both notes shall be applied accumulatively. e. Maximum allowable quantities shall be increased 100 percent when stored in approved storage cabinets, day boxes, gas cabinets, gas rooms or exhausted enclosures or in listed safety cans in accordance with Clause 5003.9.10 of the Ghana Fire Code. Where Note d also applies, the increase for both notes shall be applied accumulatively. f. Quantities shall not be limited in a building equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. g. Allowed only in buildings equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. h. Containing not more than the maximum allowable quantity per control area of Class IA, IB or IC flammable liquids. i. The maximum allowable quantity shall not apply to fuel oil storage complying with the Ghana Fire Code. j. Quantities in parentheses indicate quantity units in parentheses at the head of each column. k. A maximum quantity of 220 pounds of solid or 22 gallons of liquid Class 3 oxidizers is allowed when such materials are necessary for maintenance purposes, operation or sanitation of equipment when the storage containers and the manner of storage are approved. l. Net weight of the pyrotechnic composition of the fireworks. Where the net weight of the pyrotechnic composition of the fireworks is not known, 25 percent of the gross weight of the fireworks, including packaging, shall be used. m. For gallons of liquids, divide the amount in pounds by 10 in accordance with the Ghana Fire Code. n. For storage and display quantities in Group M and storage quantities in Group S occupancies complying with this Code. o. Densely packed baled cotton that complies with the packing requirements of ISO 8115 shall not be included in this material class. p. The following shall not be included in determining the maximum allowable quantities: 1. Liquid or gaseous fuel in fuel tanks on vehicles. 2. Liquid or gaseous fuel in fuel tanks on motorized equipment operated in accordance with the Ghana Fire Code. 3. Gaseous fuels in piping systems and fixed appliances regulated by this Code. 4. Liquid fuels in piping systems and fixed appliances regulated by this Code. 5. Alcohol-based hand rubs classified as Class I or II liquids in dispensers that are installed in accordance with the Ghana Fire Code. The location of the alcohol-based hand rub (ABHR) dispensers shall be provided in the construction documents. q. Where manufactured, generated or used in such a manner that the concentration and conditions create a fire or explosion hazard based on information prepared in accordance with this Code.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-22','F','or SI: 1 cubic foot = 0','For SI: 1 cubic foot = 0.028 m3 , 1 pound = 0.454 kg, 1 gallon = 3.785 L. a. For use of control areas. b. The aggregate quantity in use and storage shall not exceed the quantity listed for storage. c. In retail and wholesale sales occupancies, the quantities of medicines, foodstuffs or consumer products, and cosmetics containing not more than 50 percent by volume of water-miscible liquids and with the remainder of the solutions not being flammable, shall not be limited, provided that such materials are packaged in individual containers not exceeding 1.3 gallons. d. Maximum allowable quantities shall be increased 100 percent in buildings equipped throughout with an approved automatic sprinkler system in accordance with this Code. Where Note e also applies, the increase for both notes shall be applied accumulatively. e. Maximum allowable quantities shall be increased 100 percent where stored in approved storage cabinets, gas cabinets or exhausted enclosures as specified in the Ghana Fire Code. Where Note d also applies, the increase for both notes shall be applied accumulatively. f. For storage and display quantities in Group M and storage quantities in Group S occupancies complying with this Code. g. Allowed only where stored in approved exhausted gas cabinets or exhausted enclosures as specified in the Ghana Fire Code. h. Quantities in parentheses indicate quantity units in parentheses at the head of each column. i. For gallons of liquids, divide the amount in pounds by 10.',3,NULL,NULL,170,'For SI: 1 cubic foot = 0.028 m3 , 1 pound = 0.454 kg, 1 gallon = 3.785 L. a. For use of control areas. b. The aggregate quantity in use and storage shall not exceed the quantity listed for storage. c. In retail and wholesale sales occupancies, the quantities of medicines, foodstuffs or consumer products, and cosmetics containing not more than 50 percent by volume of water-miscible liquids and with the remainder of the solutions not being flammable, shall not be limited, provided that such materials are packaged in individual containers not exceeding 1.3 gallons. d. Maximum allowable quantities shall be increased 100 percent in buildings equipped throughout with an approved automatic sprinkler system in accordance with this Code. Where Note e also applies, the increase for both notes shall be applied accumulatively. e. Maximum allowable quantities shall be increased 100 percent where stored in approved storage cabinets, gas cabinets or exhausted enclosures as specified in the Ghana Fire Code. Where Note d also applies, the increase for both notes shall be applied accumulatively. f. For storage and display quantities in Group M and storage quantities in Group S occupancies complying with this Code. g. Allowed only where stored in approved exhausted gas cabinets or exhausted enclosures as specified in the Ghana Fire Code. h. Quantities in parentheses indicate quantity units in parentheses at the head of each column. i. For gallons of liquids, divide the amount in pounds by 10.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-23','A','n occupancy that stores, uses or handles hazardous materials as described in one or more of the following items shall not be classified as Group H, but shall be classified as the occupancy that it most nearly resembles','An occupancy that stores, uses or handles hazardous materials as described in one or more of the following items shall not be classified as Group H, but shall be classified as the occupancy that it most nearly resembles. 1. Buildings and structures occupied for the application of flammable finishes, provided that such buildings or areas conform to the requirements of the Ghana Fire Code. 2. Wholesale and retail sales and storage of flammable and combustible liquids in mercantile occupancies conforming to the Ghana Fire Code. 3. Closed piping system containing flammable or combustible liquids or gases utilized for the operation of machinery or equipment. 4. Cleaning establishments that utilize combustible liquid solvents having a flash point of 140°F (60°C) or higher in closed systems employing equipment listed by an approved testing agency, provided that this occupancy is separated from all other areas of the building by 1-hour fire barriers constructed in accordance with Clause 8.7 or 1hour horizontal assemblies constructed in accordance with Clause 8.11, or both. 5. Cleaning establishments that utilize a liquid solvent having a flash point at or above 93°C (200°F). 6. Liquor stores and distributors without bulk storage. 7. Refrigeration systems. 8. The storage or utilization of materials for agricultural purposes on the premises. 9. Stationary storage battery systems installed in accordance with the Ghana Fire Code. 10. Corrosive personal or household products in their original packaging used in retail display. 11. Commonly used corrosive building materials. 12. Buildings and structures occupied for aerosol product storage shall be classified as Group S-1, provided that such buildings conform to the requirements of the Ghana Fire Code. 13. Display and storage of nonflammable solid and nonflammable or noncombustible liquid hazardous materials in quantities not exceeding the maximum allowable quantity per control area in Group M or S occupancies complying with this Code. 14. The storage of black powder, smokeless propellant and small arms primers in Groups M and R-3 and special industrial explosive devices in Groups B, F, M and S, provided such storage conforms to the quantity limits and requirements prescribed in the Ghana Fire Code. 15. Stationary fuel cell power systems installed in accordance with the Ghana Fire Code. 16. Capacitor energy storage systems in accordance with the Ghana Fire Code. 17. Group B higher education laboratory occupancies complying with this Code and of the Ghana Fire Code.',3,NULL,'3.7.1.1',171,'An occupancy that stores, uses or handles hazardous materials as described in one or more of the following items shall not be classified as Group H, but shall be classified as the occupancy that it most nearly resembles. 1. Buildings and structures occupied for the application of flammable finishes, provided that such buildings or areas conform to the requirements of the Ghana Fire Code. 2. Wholesale and retail sales and storage of flammable and combustible liquids in mercantile occupancies conforming to the Ghana Fire Code. 3. Closed piping system containing flammable or combustible liquids or gases utilized for the operation of machinery or equipment. 4. Cleaning establishments that utilize combustible liquid solvents having a flash point of 140°F (60°C) or higher in closed systems employing equipment listed by an approved testing agency, provided that this occupancy is separated from all other areas of the building by 1-hour fire barriers constructed in accordance with Clause 8.7 or 1hour horizontal assemblies constructed in accordance with Clause 8.11, or both. 5. Cleaning establishments that utilize a liquid solvent having a flash point at or above 93°C (200°F). 6. Liquor stores and distributors without bulk storage. 7. Refrigeration systems. 8. The storage or utilization of materials for agricultural purposes on the premises. 9. Stationary storage battery systems installed in accordance with the Ghana Fire Code. 10. Corrosive personal or household products in their original packaging used in retail display. 11. Commonly used corrosive building materials. 12. Buildings and structures occupied for aerosol product storage shall be classified as Group S-1, provided that such buildings conform to the requirements of the Ghana Fire Code. 13. Display and storage of nonflammable solid and nonflammable or noncombustible liquid hazardous materials in quantities not exceeding the maximum allowable quantity per control area in Group M or S occupancies complying with this Code. 14. The storage of black powder, smokeless propellant and small arms primers in Groups M and R-3 and special industrial explosive devices in Groups B, F, M and S, provided such storage conforms to the quantity limits and requirements prescribed in the Ghana Fire Code. 15. Stationary fuel cell power systems installed in accordance with the Ghana Fire Code. 16. Capacitor energy storage systems in accordance with the Ghana Fire Code. 17. Group B higher education laboratory occupancies complying with this Code and of the Ghana Fire Code.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-24','H','azardous materials in any quantity shall conform to the requirements of this Code, including Clause 4','Hazardous materials in any quantity shall conform to the requirements of this Code, including Clause 4.14, and the Ghana Fire Code.',3,NULL,'3.7.2',171,'Hazardous materials in any quantity shall conform to the requirements of this Code, including Clause 4.14, and the Ghana Fire Code.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-25','B','uildings and structures containing materials that pose a detonation hazard shall be classified as Group H-1','Buildings and structures containing materials that pose a detonation hazard shall be classified as Group H-1. Such materials shall include, but not be limited to, the following: Detonable pyrophoric materials Explosives: Division 1.1 Division 1.2 Division 1.3 Division 1.4 Division 1.5 Division 1.6 Organic peroxides, unclassified detonable Oxidizers, Class 4 Unstable (reactive) materials, Class 3 detonable and Class 4',3,NULL,'3.7.3',171,'Buildings and structures containing materials that pose a detonation hazard shall be classified as Group H-1. Such materials shall include, but not be limited to, the following: Detonable pyrophoric materials Explosives: Division 1.1 Division 1.2 Division 1.3 Division 1.4 Division 1.5 Division 1.6 Organic peroxides, unclassified detonable Oxidizers, Class 4 Unstable (reactive) materials, Class 3 detonable and Class 4');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-26','B','uildings and structures containing materials that pose a deflagration hazard or a hazard from accelerated burning shall be classified as Group H-2','Buildings and structures containing materials that pose a deflagration hazard or a hazard from accelerated burning shall be classified as Group H-2. Such materials shall include, but not be limited to, the following: Class I, II or IIIA flammable or combustible liquids that are used or stored in normally open containers or systems, or in closed containers or systems pressurized at more than 15 pounds per square inch gauge (103.4 kPa). Combustible dusts where manufactured, generated or used in such a manner that the concentration and conditions create a fire or explosion hazard based on information prepared in accordance with this Code. Cryogenic fluids, flammable. Flammable gases. Organic peroxides, Class I. Oxidizers, Class 3, that are used or stored in normally open containers or systems, or in closed containers or systems pressurized at more than 15 pounds per square inch gauge (103 kPa). Pyrophoric liquids, solids and gases, nondetonable. Unstable (reactive) materials, Class 3, nondetonable. Water-reactive materials, Class 3.',3,NULL,'3.7.4',172,'Buildings and structures containing materials that pose a deflagration hazard or a hazard from accelerated burning shall be classified as Group H-2. Such materials shall include, but not be limited to, the following: Class I, II or IIIA flammable or combustible liquids that are used or stored in normally open containers or systems, or in closed containers or systems pressurized at more than 15 pounds per square inch gauge (103.4 kPa). Combustible dusts where manufactured, generated or used in such a manner that the concentration and conditions create a fire or explosion hazard based on information prepared in accordance with this Code. Cryogenic fluids, flammable. Flammable gases. Organic peroxides, Class I. Oxidizers, Class 3, that are used or stored in normally open containers or systems, or in closed containers or systems pressurized at more than 15 pounds per square inch gauge (103 kPa). Pyrophoric liquids, solids and gases, nondetonable. Unstable (reactive) materials, Class 3, nondetonable. Water-reactive materials, Class 3.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-27','B','uildings and structures containing materials that readily support combustion or that pose a physical hazard shall be classified as Group H3','Buildings and structures containing materials that readily support combustion or that pose a physical hazard shall be classified as Group H3. Such materials shall include, but not be limited to, the following: Class I, II or IIIA flammable or combustible liquids that are used or stored in normally closed containers or systems pressurized at 15 pounds per square inch gauge (103.4 kPa) or less. Combustible fibers, other than densely packed baled cotton, where manufactured, generated or used in such a manner that the concentration and conditions create a fire or explosion hazard based on information prepared in accordance with Clause 4.14.1.3. Consumer fireworks, 1.4G (Class C, Common) Cryogenic fluids, oxidizing Flammable solids Organic peroxides, Class II and III Oxidizers, Class 2 Oxidizers, Class 3, that are used or stored in normally closed containers or systems pressurized at 15 pounds per square inch gauge (103 kPa) or less Oxidizing gases Unstable (reactive) materials, Class 2 Water-reactive materials, Class 2',3,NULL,'3.7.5',172,'Buildings and structures containing materials that readily support combustion or that pose a physical hazard shall be classified as Group H3. Such materials shall include, but not be limited to, the following: Class I, II or IIIA flammable or combustible liquids that are used or stored in normally closed containers or systems pressurized at 15 pounds per square inch gauge (103.4 kPa) or less. Combustible fibers, other than densely packed baled cotton, where manufactured, generated or used in such a manner that the concentration and conditions create a fire or explosion hazard based on information prepared in accordance with Clause 4.14.1.3. Consumer fireworks, 1.4G (Class C, Common) Cryogenic fluids, oxidizing Flammable solids Organic peroxides, Class II and III Oxidizers, Class 2 Oxidizers, Class 3, that are used or stored in normally closed containers or systems pressurized at 15 pounds per square inch gauge (103 kPa) or less Oxidizing gases Unstable (reactive) materials, Class 2 Water-reactive materials, Class 2');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-28','B','uildings and structures containing materials that are health hazards shall be classified as Group H-4','Buildings and structures containing materials that are health hazards shall be classified as Group H-4. Such materials shall include, but not be limited to, the following: Corrosives Highly toxic materials Toxic materials',3,NULL,'3.7.6',172,'Buildings and structures containing materials that are health hazards shall be classified as Group H-4. Such materials shall include, but not be limited to, the following: Corrosives Highly toxic materials Toxic materials');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-29','S','emiconductor fabrication facilities and comparable research and development areas in which hazardous production materials (HPM) are used and the aggregate quantity of materials is in excess of those listed in Tables 3','Semiconductor fabrication facilities and comparable research and development areas in which hazardous production materials (HPM) are used and the aggregate quantity of materials is in excess of those listed in Tables 3.7.1(1) and 3.7.1(2) shall be classified as Group H-5. Such facilities and areas shall be designed and constructed in accordance with Clause 4.15.11.',3,NULL,'3.7.7',172,'Semiconductor fabrication facilities and comparable research and development areas in which hazardous production materials (HPM) are used and the aggregate quantity of materials is in excess of those listed in Tables 3.7.1(1) and 3.7.1(2) shall be classified as Group H-5. Such facilities and areas shall be designed and constructed in accordance with Clause 4.15.11.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-30','B','uildings and structures containing a material or materials representing hazards that are','Buildings and structures containing a material or materials representing hazards that are classified in one or more of Groups H-1, H-2, H-3 and H-4 shall conform to the Code requirements for each of the occupancies so classified.',3,NULL,'3.7.8',172,'Buildings and structures containing a material or materials representing hazards that are classified in one or more of Groups H-1, H-2, H-3 and H-4 shall conform to the Code requirements for each of the occupancies so classified.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-31','I','nstitutional Group I occupancy includes, among others, the use of a building or structure, or a portion thereof, in which care or supervision is provided to persons who are or are not capable of self-preservation without physical assistance or in which persons are detained for penal or correctional purposes or in which the liberty of the occupants is restricted','Institutional Group I occupancy includes, among others, the use of a building or structure, or a portion thereof, in which care or supervision is provided to persons who are or are not capable of self-preservation without physical assistance or in which persons are detained for penal or correctional purposes or in which the liberty of the occupants is restricted. Institutional occupancies shall be classified as Group I-1, I-2, I-3 or I-4.',3,'3.8','3.8.1',173,'Institutional Group I occupancy includes, among others, the use of a building or structure, or a portion thereof, in which care or supervision is provided to persons who are or are not capable of self-preservation without physical assistance or in which persons are detained for penal or correctional purposes or in which the liberty of the occupants is restricted. Institutional occupancies shall be classified as Group I-1, I-2, I-3 or I-4.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-32','I','nstitutional Group I-1 occupancy shall include buildings, structures or portions thereof for more than 16 persons, excluding staff, who reside on a 24-hour basis in a supervised environment and receive custodial care','Institutional Group I-1 occupancy shall include buildings, structures or portions thereof for more than 16 persons, excluding staff, who reside on a 24-hour basis in a supervised environment and receive custodial care. Buildings of Group I-1 shall be classified as one of the occupancy conditions specified in Clause 3.8.2.1 or 3.8.2.2. This group shall include, but not be limited to, the following: Alcohol and drug centers Assisted living facilities Congregate care facilities Group homes Halfway houses Residential board and care facilities Social rehabilitation facilities',3,'3.8','3.8.2',173,'Institutional Group I-1 occupancy shall include buildings, structures or portions thereof for more than 16 persons, excluding staff, who reside on a 24-hour basis in a supervised environment and receive custodial care. Buildings of Group I-1 shall be classified as one of the occupancy conditions specified in Clause 3.8.2.1 or 3.8.2.2. This group shall include, but not be limited to, the following: Alcohol and drug centers Assisted living facilities Congregate care facilities Group homes Halfway houses Residential board and care facilities Social rehabilitation facilities');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-33','T','his occupancy condition shall include buildings in which all persons receiving custodial care who, without any assistance, are capable of responding to an emergency situation to complete building evacuation','This occupancy condition shall include buildings in which all persons receiving custodial care who, without any assistance, are capable of responding to an emergency situation to complete building evacuation.',3,'3.8','3.8.2.1',173,'This occupancy condition shall include buildings in which all persons receiving custodial care who, without any assistance, are capable of responding to an emergency situation to complete building evacuation.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-34','T','his occupancy condition shall include buildings in which there are any persons receiving custodial care who require limited verbal or physical assistance while responding to an emergency situation to complete building evacuation','This occupancy condition shall include buildings in which there are any persons receiving custodial care who require limited verbal or physical assistance while responding to an emergency situation to complete building evacuation.',3,'3.8','3.8.2.2',173,'This occupancy condition shall include buildings in which there are any persons receiving custodial care who require limited verbal or physical assistance while responding to an emergency situation to complete building evacuation.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-35','I','nstitutional Group I-2 occupancy shall include buildings and structures used for medical care on a 24-hour basis for more than five persons who are incapable of self-preservation','Institutional Group I-2 occupancy shall include buildings and structures used for medical care on a 24-hour basis for more than five persons who are incapable of self-preservation. This group shall include, but not be limited to, the following: Foster care facilities Detoxification facilities Hospitals Nursing homes Psychiatric hospitals',3,'3.8','3.8.3',173,'Institutional Group I-2 occupancy shall include buildings and structures used for medical care on a 24-hour basis for more than five persons who are incapable of self-preservation. This group shall include, but not be limited to, the following: Foster care facilities Detoxification facilities Hospitals Nursing homes Psychiatric hospitals');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-36','B','uildings of Group I-2 shall be classified as one of the occupancy conditions specified in Clause 3','Buildings of Group I-2 shall be classified as one of the occupancy conditions specified in Clause 3.8.3.1.1 or 3.8.3.1.2.',3,'3.8','3.8.3.1',173,'Buildings of Group I-2 shall be classified as one of the occupancy conditions specified in Clause 3.8.3.1.1 or 3.8.3.1.2.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-37','T','his occupancy condition shall include facilities that provide nursing and medical care but do not provide emergency care, surgery, obstetrics or in-patient stabilization units for psychiatric or detoxification, including but not limited to nursing homes and foster care facilities','This occupancy condition shall include facilities that provide nursing and medical care but do not provide emergency care, surgery, obstetrics or in-patient stabilization units for psychiatric or detoxification, including but not limited to nursing homes and foster care facilities.',3,'3.8','3.8.3.1.1',173,'This occupancy condition shall include facilities that provide nursing and medical care but do not provide emergency care, surgery, obstetrics or in-patient stabilization units for psychiatric or detoxification, including but not limited to nursing homes and foster care facilities.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-38','T','his occupancy condition shall include facilities that provide nursing and medical care and could provide emergency care, surgery, obstetrics or in-patient stabilization units for psychiatric or detoxification, including but not limited to hospitals','This occupancy condition shall include facilities that provide nursing and medical care and could provide emergency care, surgery, obstetrics or in-patient stabilization units for psychiatric or detoxification, including but not limited to hospitals.',3,'3.8','3.8.3.1.2',173,'This occupancy condition shall include facilities that provide nursing and medical care and could provide emergency care, surgery, obstetrics or in-patient stabilization units for psychiatric or detoxification, including but not limited to hospitals.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-39','I','nstitutional Group I-3 occupancy shall include buildings and structures that are inhabited by more than five persons who are under restraint or security','Institutional Group I-3 occupancy shall include buildings and structures that are inhabited by more than five persons who are under restraint or security. A Group I-3 facility is occupied by persons who are generally incapable of selfpreservation due to security measures not under the occupants‘ control. This group shall include, but not be limited to, the following: Correctional centers Detention centers Jails Prerelease centers Prisons Reformatories Buildings of Group I-3 shall be classified as one of the occupancy conditions specified in Clauses 3.8.4.1 through 3.8.4.5 (see Clause 4.8.1).',3,'3.8','3.8.4',174,'Institutional Group I-3 occupancy shall include buildings and structures that are inhabited by more than five persons who are under restraint or security. A Group I-3 facility is occupied by persons who are generally incapable of selfpreservation due to security measures not under the occupants‘ control. This group shall include, but not be limited to, the following: Correctional centers Detention centers Jails Prerelease centers Prisons Reformatories Buildings of Group I-3 shall be classified as one of the occupancy conditions specified in Clauses 3.8.4.1 through 3.8.4.5 (see Clause 4.8.1).');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-40','T','his occupancy condition shall include buildings in which free movement is allowed from sleeping areas, and other spaces where access or occupancy is permitted, to the exterior via means of escape without restraint','This occupancy condition shall include buildings in which free movement is allowed from sleeping areas, and other spaces where access or occupancy is permitted, to the exterior via means of escape without restraint. A Condition 1 facility is permitted to be constructed as Group R.',3,'3.8','3.8.4.1',174,'This occupancy condition shall include buildings in which free movement is allowed from sleeping areas, and other spaces where access or occupancy is permitted, to the exterior via means of escape without restraint. A Condition 1 facility is permitted to be constructed as Group R.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-41','T','his occupancy condition shall include buildings in which free movement is allowed from sleeping areas and any other occupied smoke compartment to one or more other smoke compartments','This occupancy condition shall include buildings in which free movement is allowed from sleeping areas and any other occupied smoke compartment to one or more other smoke compartments. Escape to the exterior is impeded by locked exits.',3,'3.8','3.8.4.2',174,'This occupancy condition shall include buildings in which free movement is allowed from sleeping areas and any other occupied smoke compartment to one or more other smoke compartments. Escape to the exterior is impeded by locked exits.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-42','T','his occupancy condition shall include buildings in which free movement is allowed within individual smoke compartments, such as within a residential unit comprised of individual sleeping units and group activity spaces, where escape is impeded by remote-controlled release of means of escape from such a smoke compartment to another smoke compartment','This occupancy condition shall include buildings in which free movement is allowed within individual smoke compartments, such as within a residential unit comprised of individual sleeping units and group activity spaces, where escape is impeded by remote-controlled release of means of escape from such a smoke compartment to another smoke compartment.',3,'3.8','3.8.4.3',174,'This occupancy condition shall include buildings in which free movement is allowed within individual smoke compartments, such as within a residential unit comprised of individual sleeping units and group activity spaces, where escape is impeded by remote-controlled release of means of escape from such a smoke compartment to another smoke compartment.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-43','T','his occupancy condition shall include buildings in which free movement is restricted from an occupied space','This occupancy condition shall include buildings in which free movement is restricted from an occupied space. Remote-controlled release is provided to permit movement from sleeping units, activity spaces and other occupied areas within the smoke compartment to other smoke compartments.',3,'3.8','3.8.4.4',174,'This occupancy condition shall include buildings in which free movement is restricted from an occupied space. Remote-controlled release is provided to permit movement from sleeping units, activity spaces and other occupied areas within the smoke compartment to other smoke compartments.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-44','T','his occupancy condition shall include buildings in which free movement is restricted from an occupied space','This occupancy condition shall include buildings in which free movement is restricted from an occupied space. Staff-controlled manual release is provided to permit movement from sleeping units, activity spaces and other occupied areas within the smoke compartment to other smoke compartments.',3,'3.8','3.8.4.5',174,'This occupancy condition shall include buildings in which free movement is restricted from an occupied space. Staff-controlled manual release is provided to permit movement from sleeping units, activity spaces and other occupied areas within the smoke compartment to other smoke compartments.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-45','A','child day care facility that provides care for more than five but not more than 100 children 1 2 / years or less of age, where the rooms in which the children are cared for are located on2 a level of exit discharge serving such rooms and each of these child care rooms has an exit door directly to the exterior, shall be classified as Group E','A child day care facility that provides care for more than five but not more than 100 children 1 2 / years or less of age, where the rooms in which the children are cared for are located on2 a level of exit discharge serving such rooms and each of these child care rooms has an exit door directly to the exterior, shall be classified as Group E.',3,'3.8','3.8.5.1',174,'A child day care facility that provides care for more than five but not more than 100 children 1 2 / years or less of age, where the rooms in which the children are cared for are located on2 a level of exit discharge serving such rooms and each of these child care rooms has an exit door directly to the exterior, shall be classified as Group E.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-46','R','ooms and spaces within places of religious worship providing such care during religious functions shall be classified as part of the primary occupancy','Rooms and spaces within places of religious worship providing such care during religious functions shall be classified as part of the primary occupancy.',3,'3.8','3.8.5.2',174,'Rooms and spaces within places of religious worship providing such care during religious functions shall be classified as part of the primary occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-47','A','facility having five or fewer persons receiving custodial care shall be classified as part of the primary occupancy','A facility having five or fewer persons receiving custodial care shall be classified as part of the primary occupancy.',3,'3.8','3.8.5.3',174,'A facility having five or fewer persons receiving custodial care shall be classified as part of the primary occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-48','M','ercantile Group M occupancy includes, among others, the use of a building or structure or a portion thereof for the display and sale of merchandise, and involves stocks of goods, wares or merchandise incidental to such purposes and accessible to the public','Mercantile Group M occupancy includes, among others, the use of a building or structure or a portion thereof for the display and sale of merchandise, and involves stocks of goods, wares or merchandise incidental to such purposes and accessible to the public. Mercantile occupancies shall include, but not be limited to, the following: Department stores Drug stores Markets Greenhouses for display and sale of plants that provide public access. Motor fuel-dispensing facilities Retail or wholesale stores Sales rooms',3,'3.9','3.9.1',175,'Mercantile Group M occupancy includes, among others, the use of a building or structure or a portion thereof for the display and sale of merchandise, and involves stocks of goods, wares or merchandise incidental to such purposes and accessible to the public. Mercantile occupancies shall include, but not be limited to, the following: Department stores Drug stores Markets Greenhouses for display and sale of plants that provide public access. Motor fuel-dispensing facilities Retail or wholesale stores Sales rooms');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-49','T','he aggregate quantity of nonflammable solid and nonflammable or noncombustible liquid hazardous materials stored or displayed in a single control area of a Group M occupancy shall not exceed the quantities in Table 4','The aggregate quantity of nonflammable solid and nonflammable or noncombustible liquid hazardous materials stored or displayed in a single control area of a Group M occupancy shall not exceed the quantities in Table 4.14.2.5(1).',3,'3.9','3.9.2',175,'The aggregate quantity of nonflammable solid and nonflammable or noncombustible liquid hazardous materials stored or displayed in a single control area of a Group M occupancy shall not exceed the quantities in Table 4.14.2.5(1).');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-50','R','esidential Group R includes, among others, the use of a building or structure, or a portion thereof, for sleeping purposes when not classified as an Institutional Group I','Residential Group R includes, among others, the use of a building or structure, or a portion thereof, for sleeping purposes when not classified as an Institutional Group I.',3,'3.10','3.10.1',175,'Residential Group R includes, among others, the use of a building or structure, or a portion thereof, for sleeping purposes when not classified as an Institutional Group I.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-51','R','esidential Group R-1 occupancies containing sleeping units where the occupants are primarily transient in nature, including:','Residential Group R-1 occupancies containing sleeping units where the occupants are primarily transient in nature, including: Boarding houses (transient) with more than 10 occupants Congregate living facilities (transient) with more than 10 occupants Hotels (transient) Motels (transient)',3,'3.10','3.10.2',175,'Residential Group R-1 occupancies containing sleeping units where the occupants are primarily transient in nature, including: Boarding houses (transient) with more than 10 occupants Congregate living facilities (transient) with more than 10 occupants Hotels (transient) Motels (transient)');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-52','R','esidential Group R-2 occupancies containing sleeping units or more than two dwelling units where the occupants are primarily permanent in nature, including:','Residential Group R-2 occupancies containing sleeping units or more than two dwelling units where the occupants are primarily permanent in nature, including: Apartment houses Congregate living facilities (nontransient) with more than 16 occupants Boarding houses (nontransient) Convents Dormitories Fraternities and sororities Monasteries Hotels (nontransient) Live/work units Motels (nontransient) Vacation timeshare properties',3,'3.10','3.10.3',175,'Residential Group R-2 occupancies containing sleeping units or more than two dwelling units where the occupants are primarily permanent in nature, including: Apartment houses Congregate living facilities (nontransient) with more than 16 occupants Boarding houses (nontransient) Convents Dormitories Fraternities and sororities Monasteries Hotels (nontransient) Live/work units Motels (nontransient) Vacation timeshare properties');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-53','R','esidential Group R-3 occupancies where the occupants are primarily permanent in nature and not classified as Group R-1, R-2, R-4 or I, including:','Residential Group R-3 occupancies where the occupants are primarily permanent in nature and not classified as Group R-1, R-2, R-4 or I, including: Buildings that do not contain more than two dwelling units Care facilities that provide accommodations for five or fewer persons receiving care Congregate living facilities (nontransient) with 16 or fewer occupants Boarding houses (nontransient) Convents Dormitories Fraternities and sororities Monasteries Congregate living facilities (transient) with 10 or fewer occupants Boarding houses (transient) Lodging houses (transient) with five or fewer guest rooms and 10 or fewer occupants',3,'3.10','3.10.4',175,'Residential Group R-3 occupancies where the occupants are primarily permanent in nature and not classified as Group R-1, R-2, R-4 or I, including: Buildings that do not contain more than two dwelling units Care facilities that provide accommodations for five or fewer persons receiving care Congregate living facilities (nontransient) with 16 or fewer occupants Boarding houses (nontransient) Convents Dormitories Fraternities and sororities Monasteries Congregate living facilities (transient) with 10 or fewer occupants Boarding houses (transient) Lodging houses (transient) with five or fewer guest rooms and 10 or fewer occupants');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-54','C','are facilities for five or fewer persons receiving care that are within a single-family dwelling are permitted to comply with this Code provided an automatic sprinkler system is installed in accordance with Clause 10','Care facilities for five or fewer persons receiving care that are within a single-family dwelling are permitted to comply with this Code provided an automatic sprinkler system is installed in accordance with Clause 10.3.3.1.3.',3,'3.10','3.10.4.1',175,'Care facilities for five or fewer persons receiving care that are within a single-family dwelling are permitted to comply with this Code provided an automatic sprinkler system is installed in accordance with Clause 10.3.3.1.3.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-55','O','wner-occupied lodging houses with five or fewer guest rooms and 10 or fewer total occupants shall be permitted to be constructed in accordance with this Code','Owner-occupied lodging houses with five or fewer guest rooms and 10 or fewer total occupants shall be permitted to be constructed in accordance with this Code.',3,'3.10','3.10.4.2',175,'Owner-occupied lodging houses with five or fewer guest rooms and 10 or fewer total occupants shall be permitted to be constructed in accordance with this Code.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-56','R','esidential Group R-4 occupancy shall include buildings, structures or portions thereof for more than five but not more than 16 persons, excluding staff, who reside on a 24-hour basis in a supervised residential environment and receive custodial care','Residential Group R-4 occupancy shall include buildings, structures or portions thereof for more than five but not more than 16 persons, excluding staff, who reside on a 24-hour basis in a supervised residential environment and receive custodial care. Buildings of Group R-4 shall be classified as one of the occupancy conditions specified in Clause 3.10.5.1 or 3.10.5.2. This group shall include, but not be limited to, the following: Alcohol and drug centers Assisted living facilities Congregate care facilities Group homes Halfway houses Residential board and care facilities Social rehabilitation facilities Group R-4 occupancies shall meet the requirements for construction as defined for Group R-3, except as otherwise provided for in this Code.',3,'3.10','3.10.5',175,'Residential Group R-4 occupancy shall include buildings, structures or portions thereof for more than five but not more than 16 persons, excluding staff, who reside on a 24-hour basis in a supervised residential environment and receive custodial care. Buildings of Group R-4 shall be classified as one of the occupancy conditions specified in Clause 3.10.5.1 or 3.10.5.2. This group shall include, but not be limited to, the following: Alcohol and drug centers Assisted living facilities Congregate care facilities Group homes Halfway houses Residential board and care facilities Social rehabilitation facilities Group R-4 occupancies shall meet the requirements for construction as defined for Group R-3, except as otherwise provided for in this Code.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-57','T','his occupancy condition shall include buildings in which all persons receiving custodial care, without any assistance, are capable of responding to an emergency situation to complete building evacuation','This occupancy condition shall include buildings in which all persons receiving custodial care, without any assistance, are capable of responding to an emergency situation to complete building evacuation.',3,'3.10','3.10.5.1',176,'This occupancy condition shall include buildings in which all persons receiving custodial care, without any assistance, are capable of responding to an emergency situation to complete building evacuation.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-58','T','his occupancy condition shall include buildings in which there are any persons receiving custodial care who require limited verbal or physical assistance while responding to an emergency situation to complete building evacuation','This occupancy condition shall include buildings in which there are any persons receiving custodial care who require limited verbal or physical assistance while responding to an emergency situation to complete building evacuation.',3,'3.10','3.10.5.2',176,'This occupancy condition shall include buildings in which there are any persons receiving custodial care who require limited verbal or physical assistance while responding to an emergency situation to complete building evacuation.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-59','S','torage Group S occupancy includes, among others, the use of a building or structure, or a portion thereof, for storage that is not classified as a hazardous occupancy','Storage Group S occupancy includes, among others, the use of a building or structure, or a portion thereof, for storage that is not classified as a hazardous occupancy.',3,'3.11','3.11.1',176,'Storage Group S occupancy includes, among others, the use of a building or structure, or a portion thereof, for storage that is not classified as a hazardous occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-60','A','room or space used for storage purposes that is accessory to another occupancy shall be classified as part of that occupancy','A room or space used for storage purposes that is accessory to another occupancy shall be classified as part of that occupancy.',3,'3.11','3.11.1.1',176,'A room or space used for storage purposes that is accessory to another occupancy shall be classified as part of that occupancy.');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-61','S','torage Group S-1 occupancies are buildings occupied for storage uses that are not classified as Group S-2, including, but not limited to, storage of the following:','Storage Group S-1 occupancies are buildings occupied for storage uses that are not classified as Group S-2, including, but not limited to, storage of the following: Aerosol products, Levels 2 and 3 Aircraft hangar (storage and repair) Bags: cloth, burlap and paper Bamboos and rattan Baskets Belting: canvas and leather Books and paper in rolls or packs Boots and shoes Buttons, including cloth covered, pearl or bone Cardboard and cardboard boxes Clothing, woolen wearing apparel Cordage Dry boat storage (indoor) Furniture Furs Glues, mucilage, pastes and size Grains Horns and combs, other than celluloid Leather Linoleum Timber Motor vehicle repair garages complying with the maximum allowable quantities of hazardous materials listed in Table 3.7.1(1) (see Clause 4.6.8) Photo engravings Resilient flooring Self-service storage facility (mini-storage) Silks Soaps Sugar Tires, bulk storage of Tobacco, cigars, cigarettes and snuff Upholstery and mattresses Wax candles',3,'3.11','3.11.2',176,'Storage Group S-1 occupancies are buildings occupied for storage uses that are not classified as Group S-2, including, but not limited to, storage of the following: Aerosol products, Levels 2 and 3 Aircraft hangar (storage and repair) Bags: cloth, burlap and paper Bamboos and rattan Baskets Belting: canvas and leather Books and paper in rolls or packs Boots and shoes Buttons, including cloth covered, pearl or bone Cardboard and cardboard boxes Clothing, woolen wearing apparel Cordage Dry boat storage (indoor) Furniture Furs Glues, mucilage, pastes and size Grains Horns and combs, other than celluloid Leather Linoleum Timber Motor vehicle repair garages complying with the maximum allowable quantities of hazardous materials listed in Table 3.7.1(1) (see Clause 4.6.8) Photo engravings Resilient flooring Self-service storage facility (mini-storage) Silks Soaps Sugar Tires, bulk storage of Tobacco, cigars, cigarettes and snuff Upholstery and mattresses Wax candles');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-62','S','torage Group S-2 occupancies include, among others, buildings used for the storage of noncombustible materials such as products on wood pallets or in paper cartons with or without single thickness divisions; or in paper wrappings','Storage Group S-2 occupancies include, among others, buildings used for the storage of noncombustible materials such as products on wood pallets or in paper cartons with or without single thickness divisions; or in paper wrappings. Such products are permitted to have a negligible amount of plastic trim, such as knobs, handles or film wrapping. Group S-2 storage uses shall include, but not be limited to, storage of the following: Beverages up to and including 16-percent alcohol in metal, glass or ceramic containers Cement in bags Chalk and crayons Dairy products in nonwaxed coated paper containers Dry cell batteries Electrical coils Electrical motors Empty cans Food products Foods in noncombustible containers Fresh fruits and vegetables in nonplastic trays or containers Frozen foods Glass Glass bottles, empty or filled with noncombustible liquids Gypsum board Inert pigments Ivory Meats Metal cabinets Metal desks with plastic tops and trim Metal parts Metals Mirrors Oil-filled and other types of distribution transformers Parking garages, open or enclosed Porcelain and pottery Stoves Talc and soapstones Washers and dryers',3,'3.11','3.11.3',176,'Storage Group S-2 occupancies include, among others, buildings used for the storage of noncombustible materials such as products on wood pallets or in paper cartons with or without single thickness divisions; or in paper wrappings. Such products are permitted to have a negligible amount of plastic trim, such as knobs, handles or film wrapping. Group S-2 storage uses shall include, but not be limited to, storage of the following: Beverages up to and including 16-percent alcohol in metal, glass or ceramic containers Cement in bags Chalk and crayons Dairy products in nonwaxed coated paper containers Dry cell batteries Electrical coils Electrical motors Empty cans Food products Foods in noncombustible containers Fresh fruits and vegetables in nonplastic trays or containers Frozen foods Glass Glass bottles, empty or filled with noncombustible liquids Gypsum board Inert pigments Ivory Meats Metal cabinets Metal desks with plastic tops and trim Metal parts Metals Mirrors Oil-filled and other types of distribution transformers Parking garages, open or enclosed Porcelain and pottery Stoves Talc and soapstones Washers and dryers');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-63','B','uildings and structures of an accessory character and miscellaneous structures not classified in any specific occupancy shall be constructed, equipped and maintained to conform to the requirements of this Code commensurate with the fire and life hazard incidental to their occupancy','Buildings and structures of an accessory character and miscellaneous structures not classified in any specific occupancy shall be constructed, equipped and maintained to conform to the requirements of this Code commensurate with the fire and life hazard incidental to their occupancy. Group U shall include, but not be limited to, the following: Agricultural buildings Aircraft hangars, accessory to a one- or two-family residence (see Clause 4.12.4) Barns Carports Communication equipment structures with a gross floor area of less than 139 m2 (1,500 square feet) Fences more than 1829 mm (6 feet) in height Grain silos, accessory to a residential occupancy Livestock shelters Private garages Retaining walls Sheds Stables Tanks Towers',3,'3.12','3.12.1',177,'Buildings and structures of an accessory character and miscellaneous structures not classified in any specific occupancy shall be constructed, equipped and maintained to conform to the requirements of this Code commensurate with the fire and life hazard incidental to their occupancy. Group U shall include, but not be limited to, the following: Agricultural buildings Aircraft hangars, accessory to a one- or two-family residence (see Clause 4.12.4) Barns Carports Communication equipment structures with a gross floor area of less than 139 m2 (1,500 square feet) Fences more than 1829 mm (6 feet) in height Grain silos, accessory to a residential occupancy Livestock shelters Private garages Retaining walls Sheds Stables Tanks Towers');
INSERT OR IGNORE INTO "occupancies" ("id", "group_letter", "name", "definition", "source_part", "source_section", "source_clause", "page", "source_text") VALUES ('occ-64','G','reenhouses not classified as another occupancy shall be classified as Use Group U','Greenhouses not classified as another occupancy shall be classified as Use Group U.',3,'3.12','3.12.1.1',177,'Greenhouses not classified as another occupancy shall be classified as Use Group U.');
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-001','R-001','Stair riser height within code range','Stair riser heights shall be 178 mm (7 in) maximum and 102 mm (4 in) minimum.','GS 1207:2018, Part 11, §11.11.5.2','[{"key":"stair_riser_height","operator":"present"}]','["stair_riser_height"]','{}','[{"status":"PASS","severity":"INFORMATION","issue":"Stair riser height within code range","reason":"Provided riser height falls within the 102–178 mm range required by §11.11.5.2."},{"status":"FAIL","severity":"HIGH","issue":"Stair riser height outside permitted range","reason":"§11.11.5.2 requires riser heights 102 mm (4 in) minimum and 178 mm (7 in) maximum."}]','INFORMATION','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-002','R-002','Stair tread depth minimum','Rectangular tread depths shall be 279 mm (11 in) minimum.','GS 1207:2018, Part 11, §11.11.5.2','[{"key":"stair_tread_depth","operator":"present"}]','["stair_tread_depth"]','{}','[{"status":"PASS","severity":"INFORMATION","issue":"Stair tread depth meets minimum","reason":"Provided tread depth is not less than 279 mm (11 in)."},{"status":"FAIL","severity":"HIGH","issue":"Stair tread depth below minimum","reason":"§11.11.5.2 requires rectangular tread depths 279 mm (11 in) minimum."}]','INFORMATION','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-003','R-003','Stair clear width between handrails','Stairways shall have a clear width of 1219 mm (48 in) minimum between handrails unless sprinklered.','GS 1207:2018, Part 11, §11.9.3.2','[{"key":"stair_width","operator":"present"}]','["stair_width"]','{}','[{"status":"PASS","severity":"INFORMATION","issue":"Stair clear width meets minimum","reason":"Provided stair clear width is not less than 1219 mm (48 in), or the building is sprinklered."},{"status":"FAIL","severity":"HIGH","issue":"Stair clear width below minimum","reason":"§11.9.3.2 requires 1219 mm (48 in) minimum clear width between handrails (exception for sprinklered buildings)."}]','INFORMATION','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-004','R-004','Occupancy classification — small assembly','A building or tenant space used for assembly purposes with an occupant load of less than 50 persons shall be classified as Group B.','GS 1207:2018, Part 3, §3.3.1.1','[{"key":"occupancy","operator":"in","value":["assembly","A","A-1","A-2","A-3","A-4","A-5"]},{"key":"occupants","operator":"present"}]','["occupancy","occupants"]','{}','[{"status":"REVIEW","severity":"MEDIUM","issue":"Verify occupancy classification for small assembly space","reason":"§3.3.1.1 classifies assembly spaces with fewer than 50 occupants as Group B. Confirm the occupant load and classification."}]','MEDIUM','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-005','R-005','Two exits — occupant load or common path threshold','Two exits or exit access doorways from any space shall be provided where the design occupant load or the common path of escape travel distance exceeds the values listed in §11.6.2.1.','GS 1207:2018, Part 11, §11.6.2.1','[{"key":"occupancy","operator":"in","value":["assembly","business","educational","institutional","mercantile","residential","high-hazard"]},{"key":"occupants","operator":"present"}]','["occupants","floor_area"]','{}','[{"status":"REVIEW","severity":"HIGH","issue":"Confirm exit count against §11.6.2.1 thresholds","reason":"Two exits are required where design occupant load or common path of escape travel distance exceeds the table values in §11.6.2.1. Table values require professional confirmation."}]','HIGH','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-006','R-006','Fire sprinkler — multiple Group A fire areas sharing exits','An automatic sprinkler system shall be provided where multiple fire areas of Group A-1, A-2, A-3 or A-4 occupancies share exit or exit access components and the combined occupant load is 300 or more.','GS 1207:2018, Part 10, §10.3.2.1.7','[{"key":"occupancy","operator":"in","value":["assembly","A","A-1","A-2","A-3","A-4"]},{"key":"occupants","operator":"gte","value":300}]','["occupancy","occupants"]','{}','[{"status":"REVIEW","severity":"HIGH","issue":"Sprinkler requirement likely activated","reason":"Combined occupant load ≥300 in multiple Group A fire areas sharing exit components activates §10.3.2.1.7. Confirm fire-area sharing."}]','HIGH','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-007','R-007','Building height — storey-based building area aggregation','For buildings with more than three stories above grade plane, the total building area is limited by the aggregate sum of actual/allowable area ratios.','GS 1207:2018, Part 6, §6.10.13','[{"key":"floors","operator":"gt","value":3},{"key":"floor_area","operator":"present"}]','["floors","floor_area"]','{}','[{"status":"REVIEW","severity":"MEDIUM","issue":"Multi-storey building area aggregation applies","reason":"Buildings with more than three stories must satisfy the aggregate area ratio check in §6.10.13."}]','MEDIUM','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-008','R-008','Accessibility requirements','Public, assembly, business, educational, institutional and mercantile buildings trigger accessibility requirements (Part 12).','GS 1207:2018, Part 12','[{"key":"occupancy","operator":"in","value":["assembly","business","educational","institutional","mercantile","high-hazard"]}]','["occupancy"]','{}','[{"status":"NOT_VERIFIED","severity":"MEDIUM","issue":"Accessibility requirements apply — verify against Part 12","reason":"Part 12 (Accessibility) governs these occupancies. Extraction coverage for Part 12 is limited; verify specific requirements against the source."}]','MEDIUM','Threshold/coverage needs verification.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-009','R-009','Means of escape for multi-storey residential','Residential buildings above 3 storeys require verified fire/means-of-escape review.','GS 1207:2018, Part 6 §6.10.13, Part 10, Part 11','[{"key":"occupancy","operator":"in","value":["residential","R","R-1","R-2","R-3","R-4"]},{"key":"floors","operator":"gt","value":3}]','["floors","occupancy"]','{}','[{"status":"REVIEW","severity":"HIGH","issue":"Multi-storey residential — fire and means of escape review required","reason":"Residential buildings above three storeys activate heightened fire-protection and means-of-escape requirements. Professional review required."}]','HIGH','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-010','R-010','Small building provisions','Small buildings may qualify for reduced requirements under Part 35.','GS 1207:2018, Part 35','[{"key":"floors","operator":"lte","value":2},{"key":"floor_area","operator":"lte","value":200}]','["floors","floor_area"]','{}','[{"status":"NOT_VERIFIED","severity":"LOW","issue":"Possibly eligible for Part 35 small-building provisions","reason":"Small buildings may qualify for reduced requirements. Verify eligibility criteria in Part 35."}]','LOW','Threshold/coverage needs verification.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-011','R-011','Public assembly — occupancy load verification','Group A (assembly) occupancies need verified occupant-load and means-of-escape compliance.','GS 1207:2018, Part 3, Part 4, Part 11','[{"key":"occupancy","operator":"in","value":["assembly","A","A-1","A-2","A-3","A-4","A-5"]}]','["occupancy","occupants"]','{}','[{"status":"REVIEW","severity":"HIGH","issue":"Assembly occupancy requires verified occupant load and escape design","reason":"Group A occupancies must be designed for their occupant load with compliant means of escape (Parts 3, 4, 11)."}]','HIGH','Source verified from extracted GS 1207:2018 text.','2018',1);
INSERT OR IGNORE INTO "rules" ("id", "rule_id", "name", "description", "source_reference", "conditions_json", "input_variables_json", "calculation_json", "output_json", "severity", "explanation", "effective_date", "active") VALUES ('rule-R-012','R-012','Existing building / alteration provisions','Renovation, extension, change of use and existing-building work may be governed by Part 36 (existing buildings).','GS 1207:2018, Part 36','[{"key":"project_type","operator":"in","value":["renovation","extension","change_of_use","existing_building"]}]','["project_type"]','{}','[{"status":"NOT_VERIFIED","severity":"MEDIUM","issue":"Existing-building provisions may apply","reason":"Part 36 (Existing Buildings) governs this project type. Extraction coverage is limited; verify applicable provisions against the source."}]','MEDIUM','Threshold/coverage needs verification.','2018',1);
